    public static class MahatmaGandhi
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "In reality there are as many religions as there are individuals. Religions are different roads converging to the same point. What does it matter that we take different roads, so long as we reach the same goal. Wherein is the cause for quarreling?", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "The English have taught us that we were not one nation before and that it will require centuries before we become one nation. This is without foundation. We were one nation before they came to India. One thought inspired us. Our mode of life was the same. It was because we were one nation that they were able to establish one kingdom. Subsequently they divided us.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "One of the objects of a newspaper is to understand popular feeling and to give expression to it; another is to arouse among the people certain desirable sentiments; and the third is fearlessly to expose popular defects.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "We who seek justice will have to do justice to others.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Civilization is that mode of conduct which points out to man the path of duty. Performance of duty and observance of morality are convertible terms. To observe morality is to attain mastery over our mind and our passions. So doing, we know ourselves. The Gujarati equivalent for civilization means “good conduct”.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "It is wrong to consider that courts are established for the benefit of the people. Those who want to perpetuate their power do so through the courts. If people were to settle their own quarrels, a third party would not be able to exercise any authority over them. Truly, men were less unmanly when they settled their disputes either by fighting or by asking their relatives to decide for them. They became more unmanly and cowardly when they resorted to the courts of law. It was certainly a sign of savagery when they settled their disputes by fighting. Is it any less so, if I ask a third party to decide between you and me? Surely, the decision of a third party is not always right. The parties alone know who is right. We, in our simplicity and ignorance, imagine that a stranger, by taking our money, gives us justice.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "The only real, dignified, human doctrine is the greatest good of all, and this can only be achieved by uttermost self-sacrifice.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "We but mirror the world. All the tendencies present in the outer world are to be found in the world of our body. If we could change ourselves, the tendencies in the world would also change.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Victory attained by violence is tantamount to a defeat, for it is momentary.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "It is not true that we shall necessarily progress if our political conditions undergo a change, irrespectively of the manner in which it is brought about. If the means employed are impure, the change will not be in the direction of progress but very likely in the opposite.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "In matters of conscience, the law of majority has no place.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "When there is only a choice between cowardice and violence, I would advise violence… I would rather have India resort to arms in order to defend her honour than to remain a helpless witness to her own dishonour.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Cowardice is impotence worse than violence. The coward desires revenge but being afraid to die, he looks to others… to do the work of defense for him.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Good government is no substitute for self-government.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Complete civil disobedience is a state of peaceful revolution, a refusal to obey every single state-made law.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I have learnt through bitter experience the one supreme lesson to conserve my anger, and as heat conserved is transmuted into energy, even so our anger controlled can be transmuted into a power which can move the world.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "There are many causes that I am prepared to die for but no causes that I am prepared to kill for.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I came in contact with every known Indian anarchist in London. Their bravery impressed me, but I felt that their zeal was misguided. I felt that violence was no remedy for India's ills, and that her civilisation required the use of a different and higher weapon for self-protection.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "If India adopted the doctrine of love as an active part of her religion and introduced it in her politics. Swaraj would descend upon India from heaven. But I am painfully aware that that event is far off as yet.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Satyagraha is made of sterner stuff. There is nothing reserved and nothing secret in it.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "The pre-British period was not a period of slavery. We had some sort of swaraj under Mogul rule. In Akbar’s time the birth of a Pratap was possible, and in Aurangzeb’s time a Sivaji could flourish. Has 150 years of British rule produced any Pratap and Sivaji?", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "It has always been easier to destroy than to create.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "There is nothing in the Koran to warrant the use of force for conversion. The holy book says in the clearest language possible, “There is no compulsion in religion.” The Prophet’s whole life is a repudiation of compulsion in religion. No Mussulman, to my knowledge, has ever approved of compulsion. Islam would cease to be a world religion if it were to rely upon force for its propagation.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Cow protection to me is one of the most wonderful phenomena in human evolution. It takes the human being beyond his species. The cow to me means the entire sub-human world. Man through the cow is enjoined to realize his identity with all that lives. Why the cow was selected for apotheosis is obvious to me. The cow was in India the best companion. She was the giver of plenty. Not only did she give milk, but she also made agriculture possible. The cow is a poem of pity. One reads pity in the gentle animal. She is the mother to millions of Indian mankind. Protection of the cow means protection of the whole dumb creation of God. The ancient seer, whoever he was, began with the cow. The appeal of the lower order of creation is all the more forcible because it is speechless. Cow protection is the gift of Hinduism to the world, And Hinduism will live so along as there are Hindus to protect the cow.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I claim that in losing the spinning wheel we lost our left lung. We are, therefore, suffering from galloping consumption. The restoration of the wheel arrests the progress of the fell disease.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "There is no such thing as slow freedom. Freedom is like a birth. Till we are fully free we are slaves.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "There is a higher court than courts of justice and that is the court of conscience. It supersedes all other courts.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I hold the opinion firmly that Civil Disobedience is the purest type of constitutional agitation. Of course, it becomes degrading and despicable if its civil, i.e. non-violent character is a mere camouflage.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Disobedience without civility, discipline, discrimination, non-violence, is certain destruction. Disobedience combined with love is the living water of life. Civil disobedience is a beautiful variant to signify growth, it is not discordance which spells death.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "A man is but the product of his thoughts. What he thinks, he becomes.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Any action that is dictated by fear or by coercion of any kind ceases to be moral.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "No action which is not voluntary can be called moral.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Satan's successes are the greatest when he appears with the name of God on his lips.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "The only tyrant I accept in this world is the \"still small voice\" within me. And even though I have to face the prospect of being a minority of one, I humbly believe I have the courage to be in such a hopeless minority.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Under democracy individual liberty of opinion and action is jealously guarded.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "If one has no affection for a person or a system, one should feel free to give the fullest expression to his disaffection so long as he does not contemplate, promote, or incite violence.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Nonviolence is the first article of my faith. It is also the last article of my creed.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Non-cooperation with evil is as much a duty as is cooperation with good.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Always believe in your dreams, because if you don't, you'll still have hope.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Hinduism is a relentless pursuit after truth and if today it has become moribund, inactive, irresponsive to growth, it is because we are fatigued. As soon as the fatigue is over, Hinduism will burst forth upon the world with a brilliance perhaps never known before.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I wanted to know the best of the life of one (Muhammad) who holds today an undisputed sway over the hearts of millions of mankind. I became more than ever convinced that it was not the sword that won a place for Islam in those days in the scheme of life. It was the rigid simplicity, the utter self-effacement of the Prophet the scrupulous regard for pledges, his intense devotion to his friends and followers, his intrepidity, his fearlessness, his absolute trust in God and in his own mission. These and not the sword carried everything before them and surmounted every obstacle.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I do believe in the essential unity of man and for that matter of all that lives. Therefore I believe that if one man gains spiritually, the whole world gains with him and if one man falls, the whole world falls to that extent.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Real Swaraj will come, not by the acquisition of authority by a few, but by the acquisition of the capacity by all to resist authority when it is abused. In other words, Swaraj is to be attained by educating the masses to a sense of their capacity to regulate and control authority.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Man becomes great exactly in the degree in which he works for the welfare of his fellow-men. The best way to find yourself is to lose yourself in the service of others.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I object to violence because, when it appears to do good, the good is only temporary, the evil it does is permanent.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Self-government means continuous effort to be independent of government control, whether it is foreign government or whether it is national. Swaraj government will be a sorry affair if people look up for the regulation of every detail of life.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "What the divine author of the Mahabharata said of his great creation is equally true of Hinduism. Whatever of substance is contained in any other religion is always to be found in Hinduism, and what is not contained in it is insubstantial or unnecessary.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Seven social sins: politics without principles, wealth without work, pleasure without conscience, knowledge without character, commerce without morality, science without humanity, and worship without sacrifice.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Politics without principle, wealth without work, pleasure without conscience, knowledge without character, commerce without morality, science without humanity, and worship without sacrifice — are the seven social sins.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Disobedience is a right that belongs to every human being, and it becomes a sacred duty when it springs from civility.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Hinduism is like the Ganga, pure and unsullied at its source but taking in its course the impurities in the way. Even like the Ganga it is beneficent in its total effect. It takes a provincial form in every provinvce, but the inner substance is retained everywhere.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Our sages have taught us to learn one thing; `As in the Self, so in the Universe.' It is not possible to scan the universe as it is to scan the self. Know the self and you know the universe.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "The cry for peace will be a cry in the wilderness, so long as the spirit of nonviolence does not dominate millions of men and women. An armed conflict between nations horrifies us. But the economic war is no better than an armed conflict. This is like a surgical operation. An economic war is prolonged torture. And its ravages are no less terrible than those depicted in the literature on war properly so called. We think nothing of the other because we are used to its deadly effects. … The movement against war is sound. I pray for its success. But I cannot help the gnawing fear that the movement will fail if it does not touch the root of all evil — man's greed.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Now when we talk of brotherhood of men, we stop there and feel that all other life is there for man to exploit for his own purposes. But Hinduism excludes all exploitation.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "I do regard Islam to be a religion of peace in the same sense as Christianity, Buddhism and Hinduism are.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "It is my deliberate opinion that the essential part of the teachings of the Buddha now forms an integral part of Hinduism. It is impossible for Hindu India today to retrace her steps and go behind the great reformation that Gautama effected in Hinduism. ... What Hinduism did not assimilate of what passes as Buddhism today was not an essential part of the Buddha's life and his teachings. It is my fixed opinion that the teaching of Buddha found its full fruition in India, and it could not be otherwise, for Gautama was himself a Hindu of Hindus. He was saturated with the best that was in Hinduism, and he gave life to some of the teachings that were buried in the Vedas and which were overgrown with weeds. ... Buddha never rejected Hinduism, but he broadened its base. He gave it a new life and a new interpretation.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "An error does not become truth by reason of multiplied propagation, nor does truth become error because nobody sees it. Truth stands, even if there be no public support. It is self sustained.", Author = "Mahatma Gandhi" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Mahatma_Gandhi", Text = "A nation of three hundred million people should be ashamed to have to resort to force to bring to book one hundred thousand Englishmen. To convert them, or, if you will, even to drive them out of the country, we need, not force of arms, but force of will. If we have not the latter, we shall never get the former. If we develop the force of will, we shall find that we do not need the force of arms. Acceptance of non-violence, therefore, for the purposes mentioned by me, is the most natural and the most necessary condition of our national existence. It will teach us to husband our corporate physical strength for a better purpose, instead of dissipating it, as now, in a useless fratricidal strife, in which each party is exhausted after the effort. And every armed rebellion must be an insane act unless it is backed by the nation. But almost any item of non-cooperation fully backed by the", Author = "Mahatma Gandhi" },
        };
    }
}